<?php
declare(strict_types=1);
mysqli_report(MYSQLI_REPORT_ERROR | MYSQLI_REPORT_STRICT);

function db(): mysqli {
    $d = new mysqli(getenv('FMONITOR_DEMO_HOST') ?: '127.0.0.1', getenv('FMONITOR_DEMO_USER') ?: 'fmonitor2_demo', getenv('FMONITOR_DEMO_PASSWORD') ?: 'fmonitor2_demo_local', getenv('FMONITOR_DEMO_NAME') ?: 'fmonitor2_demo', (int) (getenv('FMONITOR_DEMO_PORT') ?: 23306));
    $d->set_charset('utf8mb4'); return $d;
}
function h(?string $v): string { return htmlspecialchars($v ?? '', ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function stateLabel(string $s): string { return ['needs_order'=>'Нужно распоряжение','order_prepared'=>'Нужен номер 1С ДО','ready_to_open'=>'Готов к открытию','working'=>'Работы открыты','completed'=>'Завершён'][$s] ?? $s; }
function nextLabel(string $s): string { return ['needs_order'=>'Сформировать распоряжение','order_prepared'=>'Внести номер 1С ДО','ready_to_open'=>'Указать фактическую дату начала','working'=>'Зафиксировать ход работ','completed'=>'Действий не требуется'][$s] ?? 'Проверить данные'; }
function stateStatusClass(string $s): string { return match ($s) { 'working', 'completed' => 'shlz-status--bright-green', 'ready_to_open' => 'shlz-status--source-blue', default => 'shlz-status--orange' }; }
function personId(mysqli $d, string $key): int { $s=$d->prepare("SELECT id FROM fm2_people WHERE source_system='demo' AND source_key=?"); $s->bind_param('s',$key);$s->execute();return (int)$s->get_result()->fetch_column(); }

$d=db(); $message='';
if ($_SERVER['REQUEST_METHOD']==='POST') {
    $caseId=(int)($_POST['case_id']??0); $action=(string)($_POST['action']??'');
    $d->begin_transaction();
    try {
        $s=$d->prepare('SELECT id,process_state FROM fm2_installation_cases WHERE id=? FOR UPDATE');$s->bind_param('i',$caseId);$s->execute();$case=$s->get_result()->fetch_assoc();
        if(!$case) throw new RuntimeException('Монтажное дело не найдено.');
        $fkr=personId($d,'fkr-1');
        if($action==='prepare') {
            if($case['process_state']!=='needs_order') throw new RuntimeException('Распоряжение уже сформировано.');
            $engineer=personId($d,'engineer-1'); $i1=personId($d,'installer-1'); $i2=personId($d,'installer-2'); $name='Распоряжение о назначении монтажной бригады';$hash=hash('sha256',$caseId.'|1|'.$engineer.'|'.$i1.'|'.$i2);
            $s=$d->prepare("INSERT INTO fm2_assignment_orders (installation_case_id,version_no,order_kind,order_status,order_date,control_engineer_person_id,organization_form,document_name,document_hash,prepared_at,prepared_by_person_id) VALUES (?,1,'initial','prepared',CURDATE(),?,'brigade',?,?,NOW(),?)");$s->bind_param('iissi',$caseId,$engineer,$name,$hash,$fkr);$s->execute();$orderId=$d->insert_id;
            $s=$d->prepare("INSERT INTO fm2_assignments (assignment_order_id,person_id,assignment_role,change_action,valid_from,full_name_snapshot,position_snapshot) SELECT ?,id,'installer','assign',CURDATE(),full_name,position_name FROM fm2_people WHERE id IN (?,?)");$s->bind_param('iii',$orderId,$i1,$i2);$s->execute();
            $s=$d->prepare("INSERT INTO fm2_assignments (assignment_order_id,person_id,assignment_role,change_action,valid_from,full_name_snapshot,position_snapshot) SELECT ?,id,'control_engineer','assign',CURDATE(),full_name,position_name FROM fm2_people WHERE id=?");$s->bind_param('ii',$orderId,$engineer);$s->execute();
            $d->query("UPDATE fm2_installation_cases SET process_state='order_prepared',updated_at=NOW(),lock_version=lock_version+1 WHERE id={$caseId}");
            $d->query("UPDATE fm2_process_tasks SET task_status='completed',completed_at=NOW(),completed_by_person_id={$fkr} WHERE installation_case_id={$caseId} AND task_type='prepare_order' AND task_status='open'");
            $d->query("INSERT INTO fm2_process_tasks (installation_case_id,task_type,assignee_role,task_status,created_at) VALUES ({$caseId},'register_number','fkr','open',NOW())");
            $message='Распоряжение сформировано и зафиксировано. Следующий шаг — номер 1С ДО.';
        } elseif($action==='register') {
            $number=trim((string)($_POST['registration_number']??'')); if($case['process_state']!=='order_prepared') throw new RuntimeException('Сначала сформируйте распоряжение.'); if($number==='') throw new RuntimeException('Укажите номер 1С ДО.');
            $s=$d->prepare("UPDATE fm2_assignment_orders SET order_status='registered',registration_number=?,registered_at=NOW(),registered_by_person_id=? WHERE installation_case_id=? AND order_status='prepared'");$s->bind_param('sii',$number,$fkr,$caseId);$s->execute();
            $d->query("UPDATE fm2_installation_cases SET process_state='ready_to_open',updated_at=NOW(),lock_version=lock_version+1 WHERE id={$caseId}");
            $d->query("UPDATE fm2_process_tasks SET task_status='completed',completed_at=NOW(),completed_by_person_id={$fkr} WHERE installation_case_id={$caseId} AND task_type='register_number' AND task_status='open'");
            $d->query("INSERT INTO fm2_process_tasks (installation_case_id,task_type,assignee_role,task_status,created_at) VALUES ({$caseId},'open_order','fkr','open',NOW())");
            $message='Номер 1С ДО сохранён. Открытие работ остаётся отдельным действием.';
        } elseif($action==='open') {
            $date=(string)($_POST['actual_start_date']??''); if($case['process_state']!=='ready_to_open') throw new RuntimeException('Нужно зарегистрированное распоряжение.'); if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)) throw new RuntimeException('Укажите фактическую дату начала.');
            $s=$d->prepare("UPDATE fm2_installation_cases SET process_state='working',actual_start_date=?,opened_at=NOW(),opened_by_person_id=?,updated_at=NOW(),lock_version=lock_version+1 WHERE id=?");$s->bind_param('sii',$date,$fkr,$caseId);$s->execute();
            $d->query("UPDATE fm2_process_tasks SET task_status='completed',completed_at=NOW(),completed_by_person_id={$fkr} WHERE installation_case_id={$caseId} AND task_type='open_order' AND task_status='open'");
            $d->query("INSERT INTO fm2_process_tasks (installation_case_id,task_type,assignee_role,due_date,task_status,created_at) VALUES ({$caseId},'inspect','control_engineer',DATE_ADD('".$d->real_escape_string($date)."',INTERVAL 7 DAY),'open',NOW())");
            $message='Работы открыты. Объект перешёл в очередь строительного контроля.';
        }
        $payload=json_encode(['action'=>$action,'message'=>$message],JSON_UNESCAPED_UNICODE);$s=$d->prepare("INSERT INTO fm2_process_events (installation_case_id,event_type,occurred_at,actor_person_id,payload_json) VALUES (?, ?, NOW(), ?, ?)");$s->bind_param('isis',$caseId,$action,$fkr,$payload);$s->execute();
        $d->commit(); header('Location: ?object='.$caseId.'&ok='.urlencode($message)); exit;
    } catch(Throwable $e) { $d->rollback(); $message=$e->getMessage(); }
}
$message=$_GET['ok']??$message; $objectId=(int)($_GET['object']??0); $search=trim((string)($_GET['q']??''));
?>
