<?php if(!$objectId): $like='%'.$search.'%';$s=$d->prepare("SELECT c.id,c.process_state,c.planned_start_date,o.order_number,o.address_text,o.entrance FROM fm2_installation_cases c JOIN fm2_objects o ON o.id=c.object_id WHERE (?='' OR o.order_number LIKE ? OR o.address_text LIKE ?) ORDER BY FIELD(c.process_state,'needs_order','order_prepared','ready_to_open','working'),c.planned_start_date LIMIT 40");$s->bind_param('sss',$search,$like,$like);$s->execute();$rows=$s->get_result(); ?>
<div class="intro"><div><h1>Заказы к открытию</h1><p>Реальные данные, рабочие действия сохраняются в новой БД.</p></div><span class="shlz-status shlz-status--neutral"><?= $rows->num_rows ?> в текущей выборке</span></div><form class="shlz-surface panel search"><label class="shlz-field"><span class="shlz-field__label">Поиск по очереди</span><span class="shlz-field__control"><input class="shlz-input" name="q" value="<?=h($search)?>" placeholder="Номер заказа или адрес"></span></label><button class="shlz-button shlz-button--primary" type="submit">Найти</button></form><section class="cards" aria-label="Заказы">
<?php while($r=$rows->fetch_assoc()): ?><a class="shlz-surface card" href="?object=<?=$r['id']?>"><div><b>Заказ № <?=h($r['order_number'])?></b><div class="muted"><?=h($r['address_text'])?> · подъезд <?=h($r['entrance'])?></div></div><div><b><?=h(date('d.m.Y',strtotime($r['planned_start_date'])))?></b><div class="muted">план начала</div></div><div><span class="shlz-status <?=stateStatusClass($r['process_state'])?>"><?=h(stateLabel($r['process_state']))?></span></div><div><b><?=h(nextLabel($r['process_state']))?></b><div class="muted">Владелец: <?=$r['process_state']==='working'?'стройконтроль':'ФКР'?></div></div></a><?php endwhile; ?></section>
<?php else: $s=$d->prepare("SELECT c.*,o.order_number,o.unom,o.address_text,o.entrance,o.district,e.factory_number,e.capacity_kg,e.floor_count,e.nominal_speed_mps,a.registration_number FROM fm2_installation_cases c JOIN fm2_objects o ON o.id=c.object_id LEFT JOIN fm2_equipment_specs e ON e.object_id=o.id LEFT JOIN fm2_assignment_orders a ON a.installation_case_id=c.id AND a.order_status IN ('prepared','registered') WHERE c.id=?");$s->bind_param('i',$objectId);$s->execute();$o=$s->get_result()->fetch_assoc();if(!$o):?><div class="shlz-notification shlz-notification--danger" role="alert"><div class="shlz-notification__content"><p class="shlz-notification__title">Объект не найден.</p></div></div><?php else:$rank=['needs_order'=>0,'order_prepared'=>1,'ready_to_open'=>2,'working'=>3];$current=$rank[$o['process_state']]??0;?>
<?php if($message):?><div class="notice-wrap"><div class="shlz-notification" role="status"><div class="shlz-notification__content"><p class="shlz-notification__title"><?=h($message)?></p></div></div></div><?php endif;?><a class="shlz-link" href="?">← К очереди</a><div class="layout" style="margin-top:var(--shlz-source-spacing-16)"><aside class="shlz-surface panel passport"><h1>Заказ № <?=h($o['order_number'])?></h1><p><?=h($o['address_text'])?> · подъезд <?=h($o['entrance'])?></p><div class="facts"><div class="fact"><span>Состояние дела</span><b><?=h(stateLabel($o['process_state']))?></b></div><div class="fact"><span>План начала</span><b><?=h(date('d.m.Y',strtotime($o['planned_start_date'])))?></b></div><div class="fact"><span>Фактическое начало</span><b><?= $o['actual_start_date']?h(date('d.m.Y',strtotime($o['actual_start_date']))):'не указано' ?></b></div><div class="fact"><span>УНОМ</span><b><?=h($o['unom']?:'—')?></b></div><div class="fact"><span>Заводской номер лифта</span><b><?=h($o['factory_number']?:'не заполнен в legacy')?></b></div></div></aside><section><div class="process"><?php foreach(['Импортирован','Распоряжение','Номер 1С ДО','Работы открыты'] as $i=>$label):?><div class="step <?=$i<$current?'done':($i===$current?'current':'')?>"><b><?=$i+1?>. <?=$label?></b><?=$i<$current?'готово':($i===$current?'текущий шаг':'ожидает')?></div><?php endforeach;?></div><div class="shlz-surface panel next"><h2>Следующее действие: <?=h(nextLabel($o['process_state']))?></h2><p>Команда доступна только когда выполнено предыдущее условие. Причина видна рядом с действием.</p>
